class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.4.0/commando_0.4.0_darwin_arm64.tar.gz"
      sha256 "90a31f146c47f9ddcff36bc8ad19c2a3ce007962e138285f5cf829aa7cc21583"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.4.0/commando_0.4.0_darwin_amd64.tar.gz"
      sha256 "509a409865c974497ffd34d07fb9b0229fb3515cbe1ec443a7a5b16fbdde058c"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.4.0/commando_0.4.0_linux_arm64.tar.gz"
      sha256 "f9f5a41cd0b6da1d6155356a3cec877193fe477813163a9a529d03b947e7aab0"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.4.0/commando_0.4.0_linux_amd64.tar.gz"
      sha256 "dfff8f9f16ce870e5cf0cc41cd6fd4896aec87cb462e9a3b835b90629ef38ae2"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
